-- GUIMMIA V76.8 - 152 sale operational rules
update public.guimmia_brain_workflows set active=false,updated_at=now() where slug='sale-private-apartment' and version<>3 and active;
-- Link the complete sale rule chain to the active V76.8 workflow.
with wf as (select id from public.guimmia_brain_workflows where slug='sale-private-apartment' and version=3), steps as (select s.id,s.code from public.guimmia_brain_workflow_steps s join wf on wf.id=s.workflow_id) update public.guimmia_brain_rules r set workflow_id=wf.id,step_id=steps.id,updated_at=now() from wf,steps where r.active and r.phase_code in ('PHASE_01_CLIENT_MANDATE','PHASE_02_OWNERSHIP_TITLE','PHASE_03_DOCUMENT_DOSSIER','PHASE_04_URBAN_CADASTRAL','PHASE_05_ENCUMBRANCES_CONDO_TAX','PHASE_06_VALUATION','PHASE_07_MARKET_READINESS','PHASE_08_PUBLISHING','PHASE_09_LEADS','PHASE_10_VISITS','PHASE_11_NEGOTIATION','PHASE_12_OFFER','PHASE_13_PRELIMINARY','PHASE_14_NOTARY_CLOSING','PHASE_15_ARCHIVE') and substring(r.code from '^(P[0-9]{2})_')=steps.code;
